// 配置済みの部屋輪郭・外壁・柱を線分に変換し、軽量な一人称ビューを描画する。
const walk={x:450,y:310,a:0,keys:new Set(),raf:0};
function rotatePoint(x,y,cx,cy,a){const r=a*Math.PI/180,dx=x-cx,dy=y-cy;return[cx+dx*Math.cos(r)-dy*Math.sin(r),cy+dx*Math.sin(r)+dy*Math.cos(r)]}
function planSegments(){const seg=[];items.forEach(i=>{if(i.type==='room'){const p=roomPoints(i).map(v=>rotatePoint(i.x+v[0]*i.w,i.y+v[1]*i.h,i.x+i.w/2,i.y+i.h/2,i.rotation));p.forEach((a,n)=>seg.push({a,b:p[(n+1)%p.length],color:i.color}))}else if(i.type==='wall'||i.type==='pillar'){const p=[[i.x,i.y],[i.x+i.w,i.y],[i.x+i.w,i.y+i.h],[i.x,i.y+i.h]].map(v=>rotatePoint(v[0],v[1],i.x+i.w/2,i.y+i.h/2,i.rotation));p.forEach((a,n)=>seg.push({a,b:p[(n+1)%p.length],color:i.color}))}});return seg}
function rayHit(px,py,angle,segments){const dx=Math.cos(angle),dy=Math.sin(angle);let best=null;segments.forEach(s=>{const sx=s.b[0]-s.a[0],sy=s.b[1]-s.a[1],den=dx*sy-dy*sx;if(Math.abs(den)<.0001)return;const qx=s.a[0]-px,qy=s.a[1]-py,t=(qx*sy-qy*sx)/den,u=(qx*dy-qy*dx)/den;if(t>0&&u>=0&&u<=1&&(!best||t<best.d))best={d:t,color:s.color}});return best}
function hexRgb(hex){const h=(hex||'#747b72').replace('#','');return[h.length===3?parseInt(h[0]+h[0],16):parseInt(h.slice(0,2),16),h.length===3?parseInt(h[1]+h[1],16):parseInt(h.slice(2,4),16),h.length===3?parseInt(h[2]+h[2],16):parseInt(h.slice(4,6),16)]}
function drawWalk(){const c=$('walkCanvas'),ctx=c.getContext('2d'),w=c.width,h=c.height,segments=planSegments();ctx.fillStyle='#cfd8d3';ctx.fillRect(0,0,w,h/2);ctx.fillStyle='#8b8277';ctx.fillRect(0,h/2,w,h/2);const fov=Math.PI/3;for(let x=0;x<w;x+=3){const ra=walk.a-fov/2+fov*x/w,hit=rayHit(walk.x,walk.y,ra,segments);if(!hit)continue;const d=Math.max(1,hit.d*Math.cos(ra-walk.a)),height=Math.min(h*1.8,15000/d),[r,g,b]=hexRgb(hit.color),shade=Math.max(.28,1-d/900);ctx.fillStyle=`rgb(${r*shade},${g*shade},${b*shade})`;ctx.fillRect(x,(h-height)/2,4,height)}ctx.fillStyle='#ffffffaa';ctx.font='13px sans-serif';ctx.fillText(`位置 ${Math.round(walk.x)}, ${Math.round(walk.y)}`,18,h-18);updateWalk();walk.raf=requestAnimationFrame(drawWalk)}
function updateWalk(){const speed=walk.keys.has('Shift')?4:2.2;if(walk.keys.has('ArrowLeft')||walk.keys.has('a'))walk.a-=.035;if(walk.keys.has('ArrowRight')||walk.keys.has('d'))walk.a+=.035;let move=0;if(walk.keys.has('ArrowUp')||walk.keys.has('w'))move=speed;if(walk.keys.has('ArrowDown')||walk.keys.has('s'))move=-speed;walk.x=Math.max(0,Math.min(canvas.clientWidth,walk.x+Math.cos(walk.a)*move));walk.y=Math.max(0,Math.min(canvas.clientHeight,walk.y+Math.sin(walk.a)*move))}
$('view3dBtn').onclick=()=>{if(!items.some(i=>i.type==='room'||i.type==='wall')){toast('部屋または外壁を追加してください');return}const room=items.find(i=>i.type==='room');if(room){walk.x=room.x+room.w/2;walk.y=room.y+room.h/2}walk.a=0;$('walkModal').classList.remove('hidden');cancelAnimationFrame(walk.raf);drawWalk()};
function closeWalk(){cancelAnimationFrame(walk.raf);walk.keys.clear();$('walkModal').classList.add('hidden')}$('closeWalkBtn').onclick=closeWalk;
window.addEventListener('keydown',e=>{if(!$('walkModal').classList.contains('hidden')){walk.keys.add(e.key);if(e.key==='Escape')closeWalk();e.preventDefault()}});window.addEventListener('keyup',e=>walk.keys.delete(e.key));
window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='z'){$('undoBtn').click();e.preventDefault()}if((e.key==='Delete'||e.key==='Backspace')&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName))$('deleteBtn').click();if(selected&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){const i=items.find(x=>x.id===selected),step=e.shiftKey?gridPx()*5:gridPx();if(i){checkpoint();if(e.key==='ArrowLeft')i.x=Math.max(0,i.x-step);if(e.key==='ArrowRight')i.x=Math.min(canvas.clientWidth-i.w,i.x+step);if(e.key==='ArrowUp')i.y=Math.max(0,i.y-step);if(e.key==='ArrowDown')i.y=Math.min(canvas.clientHeight-i.h,i.y+step);render();scheduleSave();e.preventDefault()}}});canvas.onclick=e=>{if(e.target===canvas&&mode==='select'){selected=null;render()}};
try{const d=JSON.parse(localStorage.getItem('madori-data'));if(d){items=d.items||[];if((d.dataVersion||1)<DATA_VERSION)items.forEach(i=>{i.x*=2;i.y*=2;i.w*=2;i.h*=2});items.forEach(i=>{if(i.type==='wall'){if(i.h>i.w){i.w=i.h;i.rotation=(i.rotation+90)%360}i.h=4}});$('projectName').value=d.name||'わが家のプラン A';if(d.grid)$('gridSize').value=d.grid;if(d.tatami)$('tatamiSize').value=d.tatami;const g=gridPx();canvas.style.backgroundSize=`${g}px ${g}px`;if((d.dataVersion||1)<DATA_VERSION)setTimeout(save,0)}underlayData=localStorage.getItem('madori-underlay');if(underlayData){$('planUnderlay').src=underlayData;$('planUnderlay').classList.remove('hidden');$('imageControls').classList.remove('hidden')}}catch{}setZoom($('zoom').value);render();if(items.length)setTimeout(()=>$('fitViewBtn').click(),60);
